(48084, 'Numbers 26:7', 'Numbers', 26, 7, 'د دې طایفو شمېر ۴۳۷۳۰ تنه نارینه وو.', 'د دې طایفو شمېر ۴۳۷۳۰ تنه نارینه وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_26_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
