(48090, 'Numbers 26:51', 'Numbers', 26, 51, 'په لست کې د اسراییلو د ټولو کسانو شمېر ۶۰۱۷۳۰ تنه ؤ.', 'په لست کې د اسراییلو د تولو کسانو شمېر ۶۰۱۷۳۰ تنه و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_26_51.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
