(48105, 'Leviticus 12:4', 'Leviticus', 12, 4, 'بیا باید هغه ښځه د وینې د بهېدلو څخه د پاکېدلو دپاره دري دېرش ورځې صبر وکړي. هغه باید هېڅ یو پاک شي ته لاس ورنه وړي او نه دې د پاکېدلو د ورځو د پوره کېدلو پورې سپېڅلې خېمې ته ورننوځي.', 'بیا باید هغه شجه د وینې د بهېدلو چخه د پاکېدلو دپاره دری دېرش ورجې صبر وکری. هغه باید هېچ یو پاک شی ته لاس ورنه وری او نه دې د پاکېدلو د ورجو د پوره کېدلو پورې سپېچلې خېمې ته ورننوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_12_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(48106, 'Leviticus 12:5', 'Leviticus', 12, 5, 'که چېرې هغه لور وزېږوي، دا ښځه به څوارلس ورځې ناپاکه وي، لکه څنګه چې د میاشتینۍ ناروغۍ په دوران کې ناپاکه کیږي. بیا باید هغه ښځه د وینې د بهېدلو څخه د پاکېدلو دپاره شپږشپېته ورځې صبر وکړي.', 'که چېرې هغه لور وزېزوی، دا شجه به چوارلس ورجې ناپاکه وی، لکه چنګه چې د میاشتینی ناروغی په دوران کې ناپاکه کیزی. بیا باید هغه شجه د وینې د بهېدلو چخه د پاکېدلو دپاره شپزشپېته ورجې صبر وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_12_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(48107, 'Leviticus 12:6', 'Leviticus', 12, 6, 'کله چې د یو زوی یا د یوې لور د زېږولو دپاره د پاکېدلو ورځې خلاصې شي، هغه دې د سپېڅلې خېمې د دروازې په خوله کې کاهن ته ورشي. هغه دې یو وری چې یو کلن وي د سوځېدونکې نذرانې دپاره او یوه قمري یا یوه کوتره د ګناه د نذرانې دپاره راوړي.', 'کله چې د یو زوی یا د یوې لور د زېزولو دپاره د پاکېدلو ورجې خلاصې شی، هغه دې د سپېچلې خېمې د دروازې په خوله کې کاهن ته ورشی. هغه دې یو وری چې یو کلن وی د سوجېدونکې نذرانې دپاره او یوه قمری یا یوه کوتره د ګناه د نذرانې دپاره راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_12_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(48108, 'Leviticus 12:7', 'Leviticus', 12, 7, 'کاهن به د هغې دپاره د کفارې د ادا کولو په خاطر هغه د څښتن په حضور کې وړاندې کړي او هغه ښځه به د وینې د بهېدلو څخه پاکه شي. دا اصول د هغې ښځې دپاره دي چې یو هلک یا یوه انجلۍ وزېږوي.', 'کاهن به د هغې دپاره د کفارې د ادا کولو په خاطر هغه د چشتن په حضور کې وراندې کری او هغه شجه به د وینې د بهېدلو چخه پاکه شی. دا اصول د هغې شجې دپاره دی چې یو هلک یا یوه انجلی وزېزوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_12_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(48109, 'Leviticus 12:8', 'Leviticus', 12, 8, 'که چېرې دا ښځه یو وری نه شي اخیستلی، نو دوه کوترې یا دوه قمري ګانې دې راوړي، یوه د سوځېدونکې نذرانې دپاره او بله د ګناه د نذرانې دپاره او کاهن به د هغې د ناپاکۍ د لېرې کولو دپاره کفاره ادا کړي او هغه به پاکه شي.»', 'که چېرې دا شجه یو وری نه شی اخیستلی، نو دوه کوترې یا دوه قمری ګانې دې راوری، یوه د سوجېدونکې نذرانې دپاره او بله د ګناه د نذرانې دپاره او کاهن به د هغې د ناپاکی د لېرې کولو دپاره کفاره ادا کری او هغه به پاکه شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_12_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
